mapper.select:
select analysis_tpl_id as analysisTplId, analysis_tpl_name as analysisTplName, analysis_tpl_owner analysisTplOwner, analysis_tpl_desc as analysisTplDesc, draft_status as draftStatus, online_status as onlineStatus, created_by as createdBy, created_time as createdTime, updated_by as updatedBy, updated_time as updatedTime, source_data_type as sourceDataType, has_ai_summary as hasAiSummary, analysis_tpl_type as analysisTplType from ssm_analysis_tpl_base where analysis_tpl_id in
#{id}
and is_active = 1

select analysis_tpl_id as analysisTplId, user_name as userName, created_time as createdTime
from ssm_analysis_tpl_cfg_local_lock
where analysis_tpl_id = #{analysisTplId}

mapper.update:
update ssm_analysis_tpl_widget set is_active = 0
where analysis_tpl_cfg_id = #{analysisTplCfgId}

    AND widget_id NOT IN

        #{id}

mapper.select:
select analysis_tpl_cfg_id analysisTplCfgId, analysis_tpl_id analysisTplId, analysis_tpl_content analysisTplContent, version_no versionNo, is_latest isLatest, created_by createdBy, created_time createdTime, updated_by updatedBy, updated_time updatedTime from ssm_analysis_tpl_cfg_prod where analysis_tpl_id in
#{id}
and is_latest = 1

select `analysis_tpl_cfg_id` as analysisTplCfgId, `analysis_tpl_id` as analysisTplId,
    `local_query_tpl_id` as localQueryTplId, `prod_query_tpl_id` as prodQueryTplId, `created_by` as createdBy
from `ssm_analysis_tpl_widget_query_tpl_rel`
where 1 = 1

    and analysis_tpl_cfg_id = #{analysisTplCfgId}


    and local_query_tpl_id = #{localQueryTplId}

SELECT analysis_tpl_id FROM ssm_analysis_tpl_base WHERE is_active = 1 and created_by = #{userName}
and analysis_tpl_type = #{analysisTplType}
ORDER BY updated_time DESC
